-- J4c-3 — VERIFICAÇÃO (somente leitura; só nomes e contagens). Esperado: visitante sem nada nas lojas; admin_tudo em todas; função e visão presentes.
select 'tabelas do lote presentes' as item, (select count(*) from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname in ('pedidos_revista','pedidos_popup','pedidos_wmag','pedidos_wmag_leeknow','pedidos_smolmerch','pedidos_bazaar_in','pedidos_lightstick','pedidos_popcorn_sleeve','pedidos_singba','pedidos_skzoo_rio','formulario_pedidos'))::text as valor
union all select 'com admin_tudo (esperado = presentes)', (select count(distinct tablename) from pg_policies where schemaname = 'public' and policyname = 'admin_tudo' and tablename in ('pedidos_revista','pedidos_popup','pedidos_wmag','pedidos_wmag_leeknow','pedidos_smolmerch','pedidos_bazaar_in','pedidos_lightstick','pedidos_popcorn_sleeve','pedidos_singba','pedidos_skzoo_rio','formulario_pedidos'))::text
union all select 'policies para visitante/PUBLIC (esperado 0)', (select count(*) from pg_policies where schemaname = 'public' and tablename in ('pedidos_revista','pedidos_popup','pedidos_wmag','pedidos_wmag_leeknow','pedidos_smolmerch','pedidos_bazaar_in','pedidos_lightstick','pedidos_popcorn_sleeve','pedidos_singba','pedidos_skzoo_rio','formulario_pedidos') and ('anon' = any(roles) or 'public' = any(roles)))::text
union all select 'visitante com algum privilégio nas tabelas do lote (esperado false)',
       (select coalesce(bool_or(has_table_privilege('anon', c.oid, 'SELECT') or has_table_privilege('anon', c.oid, 'INSERT') or has_table_privilege('anon', c.oid, 'UPDATE') or has_table_privilege('anon', c.oid, 'DELETE') or has_any_column_privilege('anon', c.oid, 'SELECT') or has_any_column_privilege('anon', c.oid, 'UPDATE')), false)::text
          from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname in ('pedidos_revista','pedidos_popup','pedidos_wmag','pedidos_wmag_leeknow','pedidos_smolmerch','pedidos_bazaar_in','pedidos_lightstick','pedidos_popcorn_sleeve','pedidos_singba','pedidos_skzoo_rio','formulario_pedidos'))
union all select 'pedido_loja_criar presente, seguro e aberto à loja (esperado true)', (to_regprocedure('public.pedido_loja_criar(text,jsonb)') is not null and has_function_privilege('anon', 'public.pedido_loja_criar(text,jsonb)', 'execute') and (select prosecdef and proconfig = array['search_path=""'] from pg_proc where oid = to_regprocedure('public.pedido_loja_criar(text,jsonb)')))::text
union all select 'colunas pessoais na visão pública do formulário (esperado 0)', (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'formulario_pedidos_publico' and column_name ~* '(email|nome|cog|cpf|whats)')::text
union all select 'estado registrado (linhas J4c-3, esperado >= 20)', (select count(*) from emergencia.c0b_estado_anterior where etapa = 'J4c-3')::text;
